parameters.jsCode:
const response = $input.first().json;
const config = $('CyberX AI Settings & Inputs').first().json;

let aiData = {};
try {
  const rawText = response.candidates[0].content.parts[0].text;
  aiData = JSON.parse(rawText);
} catch (e) {
  aiData = {
    headline: "CyberX: قوة الحماية الرقمية والذكاء الاصطناعي السيبراني",
    cinematic_prompt: "A high-end 3D cinematic promotional poster for CyberX digital power platform. Dark obsidian futuristic background (#0B0F19), glowing neon cyan (#00F0FF) and electric magenta (#FF007F) holographic cyber shield, intricate AI circuit networks, photorealistic 8k resolution, Unreal Engine 5 style, volumetric lighting, hyper-detailed, sleek high-tech corporate aesthetic.",
    features: ["Zero Trust Defense", "Autonomous Security", "AI Grids"],
    status: "READY_FOR_PRODUCTION"
  };
}

return {
  json: {
    execution_status: "SUCCESS ✅",
    brand: config.brand,
    model: config.ai_engine,
    headline: aiData.headline,
    cinematic_prompt: aiData.cinematic_prompt,
    features: aiData.features,
    brand_palette: {
      primary: config.primary_color,
      secondary: config.secondary_color,
      background: config.background_color
    },
    timestamp: new Date().toISOString()
  }
};
